// Transition implements mm_repository.ActionRepository
func (mmTransition *ActionRepositoryMock) Transition(ctx context.Context, t model.Transition) (sa1 []string, err error) {
	mm_atomic.AddUint64(&mmTransition.beforeTransitionCounter, 1)
	defer mm_atomic.AddUint64(&mmTransition.afterTransitionCounter, 1)

	mmTransition.t.Helper()

	if mmTransition.inspectFuncTransition != nil {
		mmTransition.inspectFuncTransition(ctx, t)
	}

	mm_params := ActionRepositoryMockTransitionParams{ctx, t}

	// Record call args
	mmTransition.TransitionMock.mutex.Lock()
	mmTransition.TransitionMock.callArgs = append(mmTransition.TransitionMock.callArgs, &mm_params)
	mmTransition.TransitionMock.mutex.Unlock()

	for _, e := range mmTransition.TransitionMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.sa1, e.results.err
		}
	}

	if mmTransition.TransitionMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmTransition.TransitionMock.defaultExpectation.Counter, 1)
		mm_want := mmTransition.TransitionMock.defaultExpectation.params
		mm_want_ptrs := mmTransition.TransitionMock.defaultExpectation.paramPtrs

		mm_got := ActionRepositoryMockTransitionParams{ctx, t}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmTransition.t.Errorf("ActionRepositoryMock.Transition got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmTransition.TransitionMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.t != nil && !minimock.Equal(*mm_want_ptrs.t, mm_got.t) {
				mmTransition.t.Errorf("ActionRepositoryMock.Transition got unexpected parameter t, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmTransition.TransitionMock.defaultExpectation.expectationOrigins.originT, *mm_want_ptrs.t, mm_got.t, minimock.Diff(*mm_want_ptrs.t, mm_got.t))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmTransition.t.Errorf("ActionRepositoryMock.Transition got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmTransition.TransitionMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmTransition.TransitionMock.defaultExpectation.results
		if mm_results == nil {
			mmTransition.t.Fatal("No results are set for the ActionRepositoryMock.Transition")
		}
		return (*mm_results).sa1, (*mm_results).err
	}
	if mmTransition.funcTransition != nil {
		return mmTransition.funcTransition(ctx, t)
	}
	mmTransition.t.Fatalf("Unexpected call to ActionRepositoryMock.Transition. %v %v", ctx, t)
	return
}

