// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ActionRepositoryMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCancelDependentsInspect()

			m.MinimockCancelPendingInspect()

			m.MinimockClaimInspect()

			m.MinimockGetInspect()

			m.MinimockGetManyInspect()

			m.MinimockInsertInspect()

			m.MinimockListInspect()

			m.MinimockListEventsInspect()

			m.MinimockListRunningInspect()

			m.MinimockTransitionInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ActionRepositoryMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ActionRepositoryMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCancelDependentsDone() &&
		m.MinimockCancelPendingDone() &&
		m.MinimockClaimDone() &&
		m.MinimockGetDone() &&
		m.MinimockGetManyDone() &&
		m.MinimockInsertDone() &&
		m.MinimockListDone() &&
		m.MinimockListEventsDone() &&
		m.MinimockListRunningDone() &&
		m.MinimockTransitionDone()
}
